-- Tastings: an occasion and an opinion, on a Vintage or loose (ADR-0003, ADR-0005).
--
-- Generated by `drizzle-kit generate` from `db/schema.ts`; the comments at the end are by
-- hand. Every invariant here is a check on the row itself, so there is no trigger.

CREATE TABLE "tastings" (
	"id" text PRIMARY KEY DEFAULT gen_prefixed_id('tst') NOT NULL,
	"vintage_id" text,
	"description" text,
	"tasted_on" date DEFAULT current_date NOT NULL,
	"place" text,
	"food" text,
	"company" text,
	"rating" numeric(2, 1),
	"notes" text,
	"liked_it" text,
	"body_and_feel" text,
	"reminded_of" text,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"edited_at" timestamp with time zone,
	CONSTRAINT "tastings_id_is_prefixed" CHECK ("tastings"."id" ~ '^tst_[a-z0-9]+(_[a-z0-9]+)*$'),
	CONSTRAINT "tastings_on_a_vintage_or_described" CHECK (("tastings"."vintage_id" is null) <> ("tastings"."description" is null)),
	CONSTRAINT "tastings_rating_is_one_to_five_in_halves" CHECK ("tastings"."rating" is null or ("tastings"."rating" between 1 and 5 and "tastings"."rating" * 2 = round("tastings"."rating" * 2))),
	CONSTRAINT "tastings_description_is_not_blank" CHECK ("tastings"."description" is null or btrim("tastings"."description") <> ''),
	CONSTRAINT "tastings_place_is_not_blank" CHECK ("tastings"."place" is null or ("tastings"."place" = btrim("tastings"."place") and "tastings"."place" <> '')),
	CONSTRAINT "tastings_food_is_not_blank" CHECK ("tastings"."food" is null or ("tastings"."food" = btrim("tastings"."food") and "tastings"."food" <> '')),
	CONSTRAINT "tastings_company_is_not_blank" CHECK ("tastings"."company" is null or ("tastings"."company" = btrim("tastings"."company") and "tastings"."company" <> '')),
	CONSTRAINT "tastings_notes_are_not_blank" CHECK ("tastings"."notes" is null or btrim("tastings"."notes") <> ''),
	CONSTRAINT "tastings_liked_it_is_not_blank" CHECK ("tastings"."liked_it" is null or btrim("tastings"."liked_it") <> ''),
	CONSTRAINT "tastings_body_and_feel_is_not_blank" CHECK ("tastings"."body_and_feel" is null or btrim("tastings"."body_and_feel") <> ''),
	CONSTRAINT "tastings_reminded_of_is_not_blank" CHECK ("tastings"."reminded_of" is null or btrim("tastings"."reminded_of") <> '')
);
